const i={ui:{fig:"Рис. 3",title:"Молния на планке",svgLabel:"Изометрический рисунок того, как молнию вшивают во вставку по верхнему краю сумки на подкладке: четыре полосы длиной с верхний край сумки, каждая лента молнии прострочена между двумя из них лицом внутрь, полосы вывернуты и отстрочены у зубчиков; концы закрыты язычками из ткани; вставка пришита к подкладке, середина к середине. В сумке молния сидит ниже верхнего края, и сумка широко открывается.",prev:"Предыдущий шаг",dot:(t,e)=>t?`Шаг ${t}: ${e}`:e,start:"Шаги →",next:"Дальше →",overview:"Обзор",stepOf:(t,e)=>`Шаг ${t} из ${e}`,machine:t=>`Машина: ${t.toLowerCase()}`,inThisStep:"В этом шаге",takeApart:"Открыть молнию",putTogether:"Закрыть молнию",replay:"↻ Повторить",parts:"Детали",allSteps:"Пошаговая инструкция",endView:"ВИД С ТОРЦА"},stitches:{straight:"Прямая строчка"},labels:{fourStrips:"четыре полосы",topLength:"длиной с верхний край",zipperLonger:"молния чуть длиннее",stripUp:"полоса лицом вверх",zipperDown:"молния лицом вниз",stripDown:"вторая полоса лицом вниз",alongEdge:"по краю",turnOut:"вывернуть",pressAway:"заутюжить от зубчиков",nearTeeth:"у зубчиков",otherSide:"вторая сторона — так же",endsTabs:"концы — как во втором способе",notOverStop:"не по ограничителю",toLining:"к подкладке",middles:"середина к середине",asUsual:"дальше верх и подкладка — как обычно",belowEdge:"ниже края",opensWide:"широко открывается"},steps:[{title:"Молния на планке в сумку",text:"Молния вшита во вставку ниже верхнего края сумки, а вставка пришита к подкладке. Нажмите, чтобы открыть молнию: сумка широко открывается."},{title:"Четыре полосы и молния",text:"Отрежьте четыре полосы длиной с верхний край сумки — по две на каждую сторону молнии — и молнию чуть длиннее полос.",details:["Отрежьте четыре полосы ткани длиной с верхний край сумки: по две на каждую сторону молнии.","Ширина полос в разных выкройках разная: чем шире полосы, тем ниже молния сидит в сумке.","Во многих выкройках на полосы приутюживают флизелин, чтобы вставка держала форму."]},{title:"Между двумя полосами",text:"Положите полосу лицом вверх, на неё — молнию лицом вниз, край к краю, сверху — вторую полосу лицом вниз: лицом внутрь.",details:["Положите одну полосу лицом вверх.","Положите на неё молнию лицом вниз, край ленты — по длинному краю полосы.","Сверху положите вторую полосу лицом вниз, срез к срезу: лента молнии теперь между двумя полосами, лицом внутрь. Сколите слои зажимами."]},{title:"Строчка по краю",text:"Лапкой для молнии прострочите по краю через три слоя: полосу, ленту молнии и вторую полосу.",details:["Поставьте лапку для молнии: с ней строчка ложится близко к зубчикам.","Прострочите по длинному краю — через обе полосы и ленту молнии.","Строчка идёт по ленте, рядом с зубчиками, а не по ним."]},{title:"Вывернуть и заутюжить",text:"Отверните полосы от молнии, изнанкой друг к другу, и заутюжьте от зубчиков.",details:["Отверните полосы от молнии: теперь молния лежит рядом с ними лицом вверх.","Две полосы лежат изнанкой друг к другу, шов спрятан между ними.","Заутюжьте полосы от зубчиков, чтобы ткань не попадала в молнию."]},{title:"Отстрочить у зубчиков",text:"Лапкой для молнии отстрочите полосу у зубчиков — через обе полосы.",details:["Отстрочите лапкой для молнии край полосы у молнии, близко к зубчикам.","Отстрочка держит обе полосы ровно и не пускает ткань в зубчики."]},{title:"Вторая сторона",text:"Вторую ленту молнии вшейте между двумя другими полосами так же, лапкой для молнии: строчка, вывернуть, заутюжить, отстрочить.",details:["Сложите две другие полосы лицом внутрь вокруг второй ленты молнии и прострочите по краю лапкой для молнии.","Выверните, заутюжьте от зубчиков и отстрочите у зубчиков.","Вставка готова: молния посередине, по две полосы с каждой стороны."]},{title:"Закрыть концы",text:"Закройте оба конца молнии язычками из ткани, как во втором способе, «Закрытые концы молнии»: строчка — сразу за ограничителем, не по нему.",details:["Сделайте два язычка из ткани и наденьте их на концы молнии — как во втором способе, «Закрытые концы молнии».","Прострочите каждый язычок лапкой для молнии сразу за ограничителем, не по нему: ограничители часто металлические, и игла может сломаться."]},{title:"К подкладке",text:"Пришейте вставку к подкладке, не к верху: каждый длинный край вставки — к верхнему краю детали подкладки, лицом к лицу, середина к середине.",details:["Отметьте середину длинных краёв вставки и верхних краёв деталей подкладки.","Сложите длинный край вставки с верхним краем детали подкладки лицом к лицу, середина к середине, и сколите зажимами.","Прострочите по краю. Второй длинный край пришейте ко второй детали подкладки так же.","Вставка идёт на подкладку, не на верх: так она оказывается внутри сумки, ниже края."]},{title:"Сумка",text:"Дальше верх и подкладку соединяют по верхнему краю, как обычно у сумки на подкладке. Молния сидит ниже края, и сумка широко открывается.",details:["Верх и подкладку соединяют по верхнему краю, как обычно у сумки на подкладке; вставка идёт вместе с подкладкой.","Молния сидит ниже верхнего края сумки.","Когда молния открыта, вставка опускается к стенкам, и сумка широко открывается."]}],legend:[{title:"Вставка",text:"четыре полосы длиной с верхний край сумки · молния посередине"},{title:"Молния",text:"чуть длиннее полос · концы закрыты язычками"},{title:"Подкладка",text:"к ней пришита вставка"},{title:"Верх",text:"соединён с подкладкой как обычно"}]};export{i as default};
